/** Auto-synced from src/data/catalog.json — run scripts/sync-catalog-data.mjs after edits. */
export const WEBSITES = {"dialup":[{"name":"GeoCities","years":"1997–2001","vibe":"Chaotic handmade pages—spinning GIFs, tiled backgrounds, MIDI autoplay, “Under Construction” banners","why":"GeoCities taught a generation that the web was something you built, not only browsed—neighborhood “homesteads,” guestbooks, and webrings were the first social graph for many kids. Its DIY pages (under construction GIFs, visitor counters, MIDI loops) defined the aesthetic grammar of personal internet identity before blogs or profiles. Yahoo’s 1999 acquisition and 2009 shutdown turned it into a foundational nostalgia ruin, preserved largely via Archive Team / Internet Archive.","cohort":"early","archive":"https://geocities.restorativland.org/"},{"name":"Angelfire","years":"1997–2002","vibe":"Templatey free-host chrome with glitter cursors, hit counters, and fan-shrine maximalism","why":"Alongside Tripod, Angelfire was the free-hosting ladder for teens who could not (or would not) buy a domain—band pages, crush shrines, fan sites, and school-project dumps lived here. Lycos’s late-90s portal empire packaged Angelfire into the same “everyone gets a homepage” moment as GeoCities. It mattered because it made web authorship feel default for ordinary kids, not just nerds with FTP access.","cohort":"early","archive":"https://www.angelfire.com/"},{"name":"Yahoo!","years":"1996–2004","vibe":"Busy purple-link portal homepage: dense directory lists, stock tickers, and web-directory taxonomy","why":"Yahoo was the front door of the consumer web—directory, search, mail, news, chat, and later GeoCities—before Google owned “just search.” Millennials learned the internet as a curated mall of categories (“Recreation,” “Society and Culture”) rather than a blank query box. Yahoo Mail and messenger later kept it sticky, but the late-90s portal identity is the formative imprint.","cohort":"both","archive":"https://www.yahoo.com/"},{"name":"AltaVista","years":"1996–2000","vibe":"Early search-engine utilitarian: big query box, advanced operators, tech-lab seriousness","why":"AltaVista was the search engine that felt like magic before Google’s minimalism won—fast full-text indexing from Digital Equipment Corporation, Babel Fish translation, and a sense that the whole web might actually be findable. For early millennials, “search” was often AltaVista or Yahoo directory first; Google arrived as the cleaner replacement. Its acquisition cascade (Compaq → CMGI → Overture → Yahoo) tracks the bubble’s rise and fall.","cohort":"early","archive":"https://web.archive.org/web/*/http://www.altavista.com/"},{"name":"Ask Jeeves","years":"1997–2003","vibe":"Friendly butler mascot, question-shaped search, soft cartoon illustration energy","why":"Ask Jeeves made search feel conversational—type a natural-language question, get answers from a cartoon butler—years before Siri/Alexa. It was kid-friendly and memorable branding in a sea of techy engines, so it stuck in school-computer folklore. Rebranded toward Ask.com after IAC’s era; Jeeves himself was retired, which only cemented the nostalgia.","cohort":"early","archive":"https://www.ask.com/"},{"name":"AOL / AOL Instant Messenger (AIM)","years":"1997–2005","vibe":"Running man logo, buddy-list sidebar, yellow away-message boxes, chunky Windows IM chrome","why":"AOL’s dial-up CDs, “You’ve Got Mail,” parental-controlled screen names, and AIM buddy lists were how millions of U.S. millennials first lived online socially. AIM taught away messages as identity performance, buddy icons as self-branding, and the etiquette of being Idle vs Available—proto-status culture. Peak AIM usage around 2001 (~36M active) overlapped early-2000s teen life even as broadband rose.","cohort":"early","archive":"https://web.archive.org/web/*/http://www.aim.com/"},{"name":"Napster","years":"1999–2001","vibe":"Sleek early-P2P client: search bar, transfer meters, cat-logo simplicity","why":"Napster made peer-to-peer music feel instantaneous and endless—albums overnight, mixtape culture at internet scale—then crashed into lawsuits that taught a generation about copyright, platforms, and sudden disappearance. It reframed music discovery as social graph + search rather than radio gatekeepers. The shutdown (and later legal relaunches) became the cautionary origin myth of the LimeWire/Kazaa era that followed.","cohort":"early","archive":"https://www.napster.com/"},{"name":"Newgrounds (early)","years":"1999–2006","vibe":"Dark portal with tank/army mascot energy, Flash embed stages, community rating meters","why":"Tom Fulp’s Newgrounds turned user-uploaded Flash games and animations into a voted portal—transgressive, funny, and craft-driven—before YouTube existed. It trained millennials as both audience and amateur creators (submit, rate, review) and incubated animators who later shaped web/TV comedy. Formative in the dial-up-to-broadband bridge years; cultural peak spills into the early-2000s band.","cohort":"early","archive":"https://www.newgrounds.com/"},{"name":"Tripod","years":"1995–2001","vibe":"College-first free host with builder wizards, pop-up ads, and Gen-X lifestyle hub chrome","why":"Tripod launched in 1995 as a Williams College–rooted community for young adults, then became one of the big three free homepage hosts beside GeoCities and Angelfire. Lycos paid ~$58M in stock for it in February 1998 to buy nearly a million 18–34 members—proof that user-built pages were the portal era’s growth engine. For early millennials, Tripod meant a memorable URL, fan sites, and the first taste of ad-supported “community” publishing before blogs.","cohort":"early","archive":"https://web.archive.org/web/*/http://www.tripod.com/"},{"name":"Hotmail (HoTMaiL)","years":"1996–2002","vibe":"Blue webmail tables, @hotmail.com flex, and inbox-in-the-browser novelty","why":"Launched July 4, 1996 as HoTMaiL—free, ad-supported, browser-based email untethered from your ISP—Hotmail made an address feel portable years before smartphones. Microsoft’s late-1997 acquisition (reported ~$400M) folded it into MSN; by early 1999 it claimed tens of millions of users. Millennials learned that identity could live at a web login: school computers, libraries, and friends’ PCs all opened the same inbox.","cohort":"early","archive":"https://web.archive.org/web/*/http://www.hotmail.com/"},{"name":"eBay","years":"1997–2001","vibe":"Yellow search chrome, auction countdowns, feedback stars, and Beanie-listing frenzy","why":"eBay turned garage-sale economics into a national spectator sport—proxy bidding, sniping, and seller feedback as reputation. The late-90s Beanie Baby bubble made auction watching a household ritual and taught kids that ordinary objects could spike in price overnight. For millennials it was commerce-as-entertainment and an early lesson in platform trust before PayPal was assumed.","cohort":"early","archive":"https://www.ebay.com/"},{"name":"ICQ","years":"1996–2001","vibe":"Flower logo, numeric UINs, Uh-oh! alert chirp, and status flowers before buddy-list polish","why":"Mirabilis launched ICQ in Nov 1996—“I seek you”—assigning numeric UINs and popularizing always-on desktop IM before AIM owned North America. AOL bought it in 1998 (~$287M+) as it raced past 100M accounts by ~2001; the Uh-oh sound, random-message culture, and UIN trading were formative for early millennials who lived online before screen names felt default. AIM/MSN later won U.S. school culture, but ICQ is the origin myth of consumer IM.","cohort":"early","archive":"https://web.archive.org/web/*/http://www.icq.com/"}],"y2k":[{"name":"Neopets","years":"2001–2007","vibe":"Bright cartoon pet-care portal: yellow submit buttons, pixel-adjacent sprites, busy sidebar nav","why":"Neopets was a full virtual economy—pets, shops, stock market, lore, Flash minigames—that colonized after-school hours and taught millennials grinding, collecting, and soft social status via Neopoints. Early millennials were teens/young adults at peak; late millennials often grew up inside it. Advertising controversy and Flash’s death never erased how completely it owned childhood browsers.","cohort":"both","archive":"https://www.neopets.com/"},{"name":"Homestar Runner","years":"2001–2009","vibe":"Chunky Flash cartoon world, toon shading, handwritten-site charm, Strong Bad’s red boxing-glove UI","why":"Homestar Runner (especially Strong Bad Email) was appointment comedy on a standalone Flash site—no ads, no login—shared via AIM links and word of mouth. It minted slang, Trogdor memes, and a sense that indie web cartoonists could be appointment media. For early millennials it was appointment internet culture; late millennials often discovered it secondhand or via later revivals.","cohort":"early","archive":"https://homestarrunner.com/"},{"name":"eBaum's World","years":"2002–2006","vibe":"Loud entertainment portal: banner ads, thumbnail grids, early-2000s shock-humor chrome","why":"eBaum’s World was the pre-YouTube boredom machine—Flash movies, shock humor, “stolen” viral clips watermarked and aggregated for mass teen traffic. Fights with Something Awful and original creators made it a morality play about attribution vs portals. Culturally it mattered as the default “send this to your friends” dump before algorithmic feeds.","cohort":"early","archive":"https://www.ebaumsworld.com/"},{"name":"MSN Messenger","years":"2002–2009","vibe":"Blue Windows messenger chrome, colorful emoticons, display-picture squares, nudge animations","why":"MSN Messenger (later Windows Live Messenger) was AIM’s global twin—emoticons, nudges, display pictures, “appear offline,” and after-school chat that defined non-AOL households and international millennial teens. Microsoft claimed 100M monthly active users by 2003, signaling IM as infrastructure. Away/status culture and wink emoticons were as formative as any social network profile.","cohort":"both","archive":"https://web.archive.org/web/*/http://messenger.msn.com/"},{"name":"LiveJournal","years":"2001–2007","vibe":"Diary-blog with mood icons, S1/S2 layouts, teal/gray classic LJ chrome, endless comment threads","why":"LiveJournal pioneered social blogging—friends lists, mutuals, comment threads, mood icons, custom CSS layouts—before “blog” meant WordPress or Tumblr. Fandom (especially media/anime/fanfic) and earnest teen diary culture thrived there; drama, flocking, and anonymous comments taught early social-media ethics. More early-millennial literary/fandom coded than late-millennial Tumblr-native.","cohort":"early","archive":"https://www.livejournal.com/"},{"name":"Xanga","years":"2002–2006","vibe":"Pastel blog templates, subscription lists, glittery teen-diary skins, metabar footers","why":"Xanga was the high-school blog network—subscriptions, blogrings, footers full of “metablog” stats—especially strong among Asian-American and suburban teens before MySpace fully peaked. It made public journaling a peer sport (who commented, who stalked). Usage time declined as MySpace/Facebook absorbed the social graph, leaving Xanga as a distinctly mid-2000s memory.","cohort":"both","archive":"https://www.xanga.com/"},{"name":"Friendster","years":"2003–2005","vibe":"Orange early-social profiles, testimonial walls, photo-forward friend networks","why":"Friendster popularized the profile + friends-of-friends social graph in the U.S. just before MySpace exploded, then famously slowed under load as users fled. It previewed testimonials, photo social proof, and “who do we know in common?” dating-adjacent networking. U.S. millennials remember the crash; Southeast Asian users kept it culturally alive longer.","cohort":"early","archive":"https://web.archive.org/web/*/http://www.friendster.com/"},{"name":"LimeWire (P2P era context)","years":"2001–2007","vibe":"Green lime client, search-result spam, progress bars, sketchy filename chaos","why":"After Napster, LimeWire (and Kazaa/BearShare) kept illicit music/movie sharing as everyday teen infrastructure—search, wait, get malware, repeat. It shaped millennial media expectations (everything available, quality random) and the moral panic / RIAA lawsuit backdrop of the decade. Court-ordered shutdown in 2010 bookends the era more than any single website UI.","cohort":"both","archive":"https://web.archive.org/web/*/http://www.limewire.com/"},{"name":"Habbo Hotel","years":"2001–2008","vibe":"Isometric pixel hotel rooms, speech bubbles, catalog furniture flex","why":"Habbo brought pixel-room socializing—trading rare furni, hotel lobbies, typed chat slang—to teens who wanted avatar presence without a full MMO install. Virtual goods and status furniture previewed later freemium worlds. Stronger late-millennial / international teen imprint than early-U.S.-AIM culture, with peak commercial heat into the late 2000s.","cohort":"late","archive":"https://www.habbo.com/"},{"name":"MapQuest","years":"2000–2006","vibe":"Printable turn-by-turn sheets, blue route lines, “start / end” form chrome, glovebox paper stacks","why":"Before in-car GPS and phones, MapQuest was how millennials drove: type two addresses, print a sheaf of steps, hope you didn’t miss exit 14B. AOL-owned MapQuest still led online mapping into the mid-2000s (tens of millions of monthly users; majority share even after Google Maps launched in 2005). The ritual of passenger-as-navigator reading “in 0.3 miles, turn right” is pure formative-year infrastructure.","cohort":"both","archive":"https://www.mapquest.com/"},{"name":"Miniclip","years":"2001–2007","vibe":"Busy Flash-game portal tiles, loud thumbnails, after-school browser tabs forever open","why":"Founded 2001 after the viral “Dancing Bush” Flash gag, Miniclip became the default browser games mall—dozens of embeds, advergames, and time-sinks that colonized school-computer labs. It was a top Flash distributor through the mid-2000s (tens of millions of monthly uniques) and even hosted early Club Penguin before Disney’s buy. For millennials it meant recess-length sessions without installing a boxed PC game.","cohort":"both","archive":"https://www.miniclip.com/"},{"name":"StumbleUpon","years":"2002–2008","vibe":"Browser toolbar with a single Stumble button, thumbs up/down, rabbit-hole serendipity","why":"Founded 2001 by University of Calgary students (Garrett Camp et al.), StumbleUpon’s toolbar sent you to semi-random interest-matched pages—thumbs training a proto-For-You feed years before TikTok. Mid-2000s growth and the 2007 eBay sale (~$75M) made “just one more Stumble” a boredom sport; later peaks still echo, but the formative muscle memory is desktop discovery before algorithmic feeds felt inevitable.","cohort":"both","archive":"https://web.archive.org/web/*/http://www.stumbleupon.com/"}],"myspace":[{"name":"MySpace","years":"2005–2008","vibe":"Chaotic custom profiles, glitter GIFs, autoplay songs, Top 8 grids, loud self-made CSS","why":"MySpace made the profile a customizable stage—HTML/CSS hacks, autoplay profile songs, Top 8 politics, bulletins—and briefly the center of teen social life and indie/emo music discovery. News Corp’s 2005 acquisition and later Facebook migration turned it into the textbook “first mainstream social network” cautionary tale. Early millennials used it as young adults; late millennials as peak-teen identity builders.","cohort":"both","archive":"https://myspace.com/"},{"name":"YouTube (early)","years":"2006–2010","vibe":"Old YouTube: gray/white player, low-res 320p embeds, star ratings, related-video stack","why":"Early YouTube replaced eBaum’s/Newgrounds flash dumps with upload-anyone video—“broadcast yourself,” lonelygirl15, viral music clips, and reply videos. It collapsed TV, webcam confessionals, and meme distribution into one player. Formative for both cohorts: early millennials as first creators/share-linkers; late millennials as native viewers.","cohort":"both","archive":"https://www.youtube.com/"},{"name":"Flickr","years":"2005–2009","vibe":"Clean pink-blue photo grid, Pro badge energy, tag clouds, geometric Web 2.0 polish","why":"Flickr made photography social—tags, favorites, groups, Creative Commons—and embodied Web 2.0’s “architecture of participation” before Instagram. Early millennials (college/young adult) used it as portfolio + community; late millennials more often skipped to Facebook photos/Instagram. Yahoo’s ownership preserved it as a tasteful niche while feeds moved elsewhere.","cohort":"early","archive":"https://www.flickr.com/"},{"name":"Digg","years":"2006–2009","vibe":"Big Digg buttons, numbered front-page lists, Web 2.0 gradients and badges","why":"Digg crowdsourced the front page—upvote tech/news/viral links—and made “making the front page” a status sport for early-millennial nerds. It previewed Reddit’s ranking culture with a glossier Web 2.0 face, then famously alienated users with the 2010 v4 redesign. Cultural peak sits squarely in the Web 2.0 rise into early social-mainstream years.","cohort":"early","archive":"https://digg.com/"},{"name":"Gaia Online","years":"2005–2009","vibe":"Anime-styled avatars, forum threads beside dress-up shops, colorful item catalogs","why":"Gaia Online fused forums, anime-adjacent avatars, gold farming, and item flex into a teen virtual hangout that competed with Habbo/Club Penguin for after-school hours. Avatar clothing and housing were identity; forums were the social glue. Stronger late-millennial teen imprint; early millennials sometimes visited but weren’t the core demographic.","cohort":"late","archive":"https://www.gaiaonline.com/"},{"name":"Club Penguin","years":"2006–2012","vibe":"Bright snowy Flash town, cute penguin avatars, colorful igloo interiors, kid-safe chat UI","why":"Club Penguin (launched 2005; Disney 2007) was the safe penguin MMO for younger millennials—igloos, puffles, moderated chat, parties—that doubled as social training wheels. Late millennials (and cusp Gen Z) formed core player base; early millennials mostly knew it as “what little siblings played.” Shutdown in 2017 sealed pure nostalgia status.","cohort":"late","archive":"https://web.archive.org/web/2010/http://www.clubpenguin.com/"},{"name":"Bebo","years":"2006–2008","vibe":"Skinnable teen profiles, quiz modules, colorful early-Facebook-adjacent social chrome","why":"Bebo was MySpace/Facebook’s UK/Ireland/ANZ counterpart—skinned profiles, quizzes, bands—often the default teen network outside the U.S. before Facebook’s global sweep. AOL’s 2008 acquisition (~$850M) and subsequent decline turned it into a regional millennial time capsule. Late millennials abroad often felt Bebo more intensely than U.S. early millennials felt MySpace’s late years.","cohort":"late","archive":"https://bebo.com/"},{"name":"Orkut","years":"2004–2010","vibe":"Simple Google-era social pages, scraps/testimonials, community topical hubs","why":"Google’s Orkut (2004) barely mattered in the U.S. but dominated Brazil and India—comunidades, scraps/testimonials, and social-graph norms that shaped huge millennial populations outside the MySpace/Facebook U.S. story. It proves formative “millennial internet” was never only American. Peak regional stickiness into the late 2000s; Google shut it down in 2014, leaving a sharp diaspora nostalgia lane and archive archaeology.","cohort":"both","archive":"https://web.archive.org/web/*/http://www.orkut.com/"},{"name":"Stickam","years":"2006–2011","vibe":"Flash webcam player, dark chat sidebar, raw bedroom-stream aesthetic","why":"Stickam (mid-2000s) made browser webcam broadcasting mainstream for teens—embeddable Flash live streams, chat sidebars, bedroom lifecasting—years before Twitch aesthetics. Musicians, cosplayers, and ordinary kids performed presence in real time; safety and moderation problems shadowed the culture. Peak registered users stretched into the early 2010s before an abrupt 2013 shutdown froze a raw pre-influencer live-video era.","cohort":"late","archive":"https://web.archive.org/web/*/http://www.stickam.com/"},{"name":"Photobucket","years":"2005–2008","vibe":"Utilitarian upload bins, hotlink URLs, slideshow widgets feeding loud profile layouts","why":"Photobucket was the image plumbing of MySpace—not a destination so much as the free host whose URLs powered profile collages, bulletins, and comment glitter. Hitwise-era data put it far ahead of Flickr for traffic; MySpace supplied a majority of visits, and Fox Interactive bought it in 2007 (~$250–300M). If you “got pics from Photobucket,” you were decorating the social web.","cohort":"both","archive":"https://photobucket.com/"},{"name":"PureVolume","years":"2003–2008","vibe":"Clean orange-to-blue music profiles, PurePicks rails, stream/download buttons without MySpace chaos","why":"Launched Thanksgiving 2003 as Unborn Media’s indie-music discovery site, PureVolume let bands stream/give away tracks with weekly PurePicks editorial—cleaner than MySpace Music and a Fueled by Ramen-era launchpad (Gym Class Heroes, Paramore, Fall Out Boy, MCR lore). Mid-2000s emo/pop-punk millennials lived between MySpace friends and PureVolume players; labels scouted it as radio’s online understudy.","cohort":"both","archive":"https://web.archive.org/web/*/http://www.purevolume.com/"},{"name":"Facebook (early / college era)","years":"2004–2007","vibe":"Clean blue-and-white college directory: minimal profiles, poke, wall, no chaos skins","why":"Early Facebook was exclusive-feeling college social graph—Thefacebook aesthetic, limited networks, poked-and-walled intimacy—before it opened to everyone and became infrastructure. Early millennials lived the invite-era prestige; late millennials mostly met the later open Facebook. This band’s Facebook is culturally distinct from 2008–2012 News Feed Facebook.","cohort":"early","archive":"https://www.facebook.com/"},{"name":"Quizilla","years":"2005–2009","vibe":"Teen quiz chrome, “What ___ are you?” results pages, chaptered story-quiz fiction","why":"Quizilla (launched Aug 2002; cultural peak mid-2000s) was the Hogwarts-house / “what kind of X are you?” factory and an unlikely home for quiz-fic and reader-insert stories before BuzzFeed owned the genre. MTV/Viacom bought it in 2006 citing millions of teen-girl uniques; the 2014 shutdown deleted profiles and sealed pure nostalgia. Late millennials lived inside its quiz results and serialized story quizzes; early millennials often remember forwarding them on AIM/MySpace.","cohort":"late","archive":"https://web.archive.org/web/20050913160246/http://www.quizilla.com/"},{"name":"YTMND","years":"2004–2008","vibe":"Single looping image/GIF + audio page, zooming zoom text, site-rating stars, subdomain meme factories","why":"You’re The Man Now Dog (ytmnd.com, community peak mid-2000s after Max Goldberg’s 2001 Connery domain joke) taught millennials the unit of the internet joke: one image, one looped sound, endless remix. By ~2006 it logged millions of monthly visitors and hundreds of thousands of user sites—pre-YouTube/Vine meme grammar (Picard Song, PTKFGS, What Is Love fads). It sits with eBaum’s/Newgrounds as formative remix culture before algorithmic short video.","cohort":"both","archive":"https://ytmnd.com/"},{"name":"Stardoll","years":"2006–2011","vibe":"Glossy paper-doll studio, Starplaza shopping, MeDoll rooms, celebrity dress-up chrome","why":"Born from Liisa Wrang’s Paperdoll Heaven and launched as Stardoll ~2005–06, it became the virtual fashion community for late-millennial girls—MeDolls, Starcoins, Starplaza shopping, and celeb dress-ups. By 2011 it claimed ~100M users (Guardian), proving browser dress-up was as formative as Neopets/Club Penguin for a huge cohort. It sits with Webkinz/Gaia as mid/late-2000s identity play that smartphones later fragmented.","cohort":"late","archive":"https://www.stardoll.com/"}],"tumblr":[{"name":"Facebook (mainstream)","years":"2008–2014","vibe":"Blue News Feed scroll, timeline photos, Like button, escalating ad/sidebar clutter","why":"Post-open Facebook + News Feed made social media default infrastructure—photos, events, groups, relationship statuses—and colonized college then everyone. By ~2012 Pew found ~86% of online U.S. 18–29s on Facebook. Early millennials settled adult identity here; late millennials finished high school inside it. This is the band where “are you on Facebook?” stopped being optional.","cohort":"both","archive":"https://www.facebook.com/"},{"name":"Tumblr","years":"2009–2014","vibe":"Infinite dashboard, soft pastel themes, GIF sets, custom themes, Ask box culture","why":"Tumblr was the reblog daisy-chain for fandom, aesthetics, activism, NSFW, and music writing—dashboard culture over friend graphs. Late millennials made it their identity workshop; early millennials often used it for niche taste but weren’t the core teen wave. Pre-Yahoo-acquisition (2013) Tumblr feels like the last major handmade-feeling mainstream social canvas.","cohort":"late","archive":"https://www.tumblr.com/"},{"name":"Reddit (early growth)","years":"2008–2013","vibe":"Sparse orange-gray link lists, upvote arrows, alien mascot, threaded comments","why":"After Digg’s 2010 redesign stumble, Reddit became the default link + comment commons—subreddits as interest graphs, upvote morality, AMA culture, and meme distribution that outlived Digg. Early millennials (college/20s) drove much of the formative culture; late millennials arrived as it was already canon. “Early Reddit” here means pre-IPO, pre-app-era Digg-refugee energy (~2008–2013), when the orange-gray list still felt like a hangout rather than a media company.","cohort":"early","archive":"https://www.reddit.com/"},{"name":"Last.fm","years":"2006–2012","vibe":"Red-black charts, artist wiki pages, scrobble graphs, music-nerd dashboard","why":"Last.fm’s scrobbling turned listening history into public identity—weekly charts pasted on MySpace/LJ sidebars, neighbor recommendations, taste as performance. CBS’s 2007 purchase and major-label streaming deals marked music-Web-2.0 maturity. Culturally it bridged P2P chaos to algorithmic taste graphs before Spotify fully won, teaching millennials that your library could be a profile. Red-black charts and artist wiki pages are the visual memory.","cohort":"both","archive":"https://www.last.fm/"},{"name":"Pandora","years":"2007–2013","vibe":"Blue radio tuner UI, album art focus, thumbs up/down, station-name simplicity","why":"Pandora’s Music Genome Project made personalized radio mainstream—thumbs up/down stations for studying, driving, dorm life—legal successor vibes to the Napster/LimeWire hunger. It taught millennials to train algorithms with micro-feedback years before Discover Weekly. Peak cultural ubiquity sits in the late-2000s/early-2010s smartphone transition.","cohort":"both","archive":"https://www.pandora.com/"},{"name":"AbsolutePunk","years":"2005–2012","vibe":"Dense music-news site + forum chrome, album cover grids, scene-kid information density","why":"AbsolutePunk was the emo/pop-punk community hub—news, reviews, forums—where Warped Tour kids tracked bands from basement to crossover (Fall Out Boy, Paramore-era ecosystem). It mattered as genre infrastructure more than mass consumer social media, and it spanned the MySpace→Tumblr migration for scene kids. Early and late millennials in that music lane shared the same dense album-cover grids and forum chrome until the brand faded into later music-press consolidation.","cohort":"both","archive":"https://web.archive.org/web/*/http://www.absolutepunk.net/"},{"name":"YouTube (culture peak handoff)","years":"2009–2012","vibe":"Maturing watch page, annotations, subscribe buttons, related-rail addiction","why":"By this band YouTube was no longer just viral clips—it was careers, beauty gurus, Let’s Plays, and the first creators-as-celebrities generation for late millennials. HD, partner program, and annotation-era culture shifted it from novelty player to primary entertainment. Overlaps early band’s “early YouTube” but the formative job here is mainstream attention platform.","cohort":"late","archive":"https://www.youtube.com/"},{"name":"Twitter","years":"2009–2014","vibe":"Minimal bird-era timeline, @replies, hashtag blue links, 140-character constraint","why":"Twitter made real-time public conversation—hashtags, retweets, following celebrities/news—core to millennial media literacy around 2009–2012 (Arab Spring, #Occupy, awards-show live-tweeting). Early millennials used it as newsroom/politics; late millennials as fandom/stan infrastructure. Shorter and more public than Tumblr dashes or Facebook walls, the bird-era 140-character constraint trained a generation’s punchline and outrage reflexes before algorithmic timelines remade the product.","cohort":"both","archive":"https://twitter.com/"},{"name":"Instagram (early)","years":"2011–2014","vibe":"Square filtered photos, vintage Valencia/X-Pro look, simple heart/comment mobile UI","why":"Early Instagram (filters, square photos, no algorithmic feed yet) closed the Flickr→Facebook photos→mobile camera loop and defined late-millennial visual self-presentation. Founded 2010, Facebook-acquired 2012; formative years are the Hipstamatic-filter social camera era. Early millennials adopted it as young adults; late millennials as late-teen natives.","cohort":"late","archive":"https://www.instagram.com/"},{"name":"LimeWire sunset / late P2P context","years":"2008–2010","vibe":"Same green P2P client fading into “service unavailable” / legal-warning endgame","why":"The court-ordered LimeWire shutdown (Oct 2010) symbolically ended the free-for-all P2P adolescence that began with Napster—pushing millennials toward YouTube rips, blogs, Pandora/Spotify, and torrents. Culturally it marks the handoff from desktop-sharing adolescence to licensed streaming adulthood. Listed here as era context rather than a beloved UI destination.","cohort":"both","archive":"https://web.archive.org/web/2010/http://www.limewire.com/"},{"name":"Formspring","years":"2009–2011","vibe":"Spare ask-me-anything feed, anonymous questions, smile reactions, teen-confession energy","why":"Launched Nov 2009, Formspring turned anonymous Q&A into a viral social sport—friends (and strangers) asking anything, answers stacking on a public profile. It hit tens of millions of monthly uniques and ~25M members by 2011, skewing late-teen/college millennials, while cyberbullying headlines shadowed the boom. It is the Tumblr-adjacent confession booth before ask.fm fully inherited the meme.","cohort":"late","archive":"https://web.archive.org/web/*/http://www.formspring.me/"},{"name":"CollegeHumor","years":"2006–2012","vibe":"Sketch-comedy portal chrome, original web series tiles, dorm-humor headlines and viral embeds","why":"Started 1999 as a dorm share site, CollegeHumor became the millennial comedy destination by the late 2000s—original sketches (Jake & Amir, Hardly Working), user-submitted gags, and ~6M monthly uniques around the IAC era/MTV show. It taught a generation that web-native comedy could be a brand, not just forwarded chain emails, bridging eBaum’s World shock dumps and YouTube sketch channels.","cohort":"late","archive":"https://www.collegehumor.com/"},{"name":"Moshi Monsters","years":"2008–2012","vibe":"Cute monster adopters, colorful flash rooms, puzzle/pinata games, kids’-social chat filters","why":"Mind Candy’s Moshi Monsters (2008) rode the Feed Years kids’-MMO wave—adopt a monster, decorate rooms, earn Rox—peaking alongside Club Penguin/Webkinz nostalgia for younger late millennials and cusp Gen Z siblings. It mattered as UK-rooted virtual-pet social play with merch crossovers before the brand’s later decline. Formative for the same after-school browser ritual as Neopets, with a brighter flash UI.","cohort":"late","archive":"https://web.archive.org/web/2012/http://www.moshimonsters.com/"}]};
export const ITEMS = {"dialup":[{"name":"Tamagotchi","category":"toy","years":"1997–1998","why":"The egg-shaped Bandai virtual pet hit U.S. shelves in 1997 and briefly owned every backpack zipper and teacher’s nerves. Millennials remember the moral panic of a beeping keychain dying in a desk because you couldn’t feed it during class.","sensory":"candy-colored plastic egg, frantic chiptune beeps, clicky rubber buttons","tag":"with a Tamagotchi"},{"name":"Game Boy (and Game Boy Color)","category":"tech","years":"1996–1999","why":"The gray brick and then the 1998 Color refresh were recess currency, especially once Pokémon Red/Blue linked play. That soft power-on chime and sideways cartridge click still teleport people to car-seat car rides.","sensory":"cool ABS shell, green LCD glow (then brighter Color screen), startup ding","tag":"Game Boy in hand"},{"name":"Beanie Babies","category":"toy","years":"1996–1999","why":"Ty’s understuffed plush with heart tags became a playground and eBay speculation mania that crested around 1999. Adults and kids treated “retired” beans like stock certificates until the bubble popped overnight.","sensory":"pellet-filled floppy body, hang-tag plastic, mild beanbag rustle","tag":"with a shelf of Beanie Babies"},{"name":"Pokémon trading cards","category":"toy","years":"1999–2000","why":"Wizards of the Coast’s U.S. Pokémon TCG (1999) detonated schoolyard Pokémania—holo Charizards, recess trade bans, ripped Base Set boosters, and binder-page economics. Parent panic and cafeteria black markets made it the millennial collectible craze that taught scarcity, negotiation, and foil-shine desire before eBay flipped the leftovers.","sensory":"foil shimmer, card-stock snap, plastic binder-sleeve squeak","tag":"with a binder of Pokémon cards"},{"name":"Lisa Frank school supplies","category":"school","years":"1995–1999","why":"Neon dolphins, rainbow leopards, and holographic folders were the late-90s locker aesthetic for a generation of girls (and plenty of boys who “borrowed” stickers). Peak annual school-supply mania made every Target aisle look like a UV poster.","sensory":"glossy rainbow ink, sticky-tack glitter, heavy folder laminate","tag":"with a Lisa Frank folder"},{"name":"Cassette Walkman (late era)","category":"music hardware","years":"1995–1998","why":"Even as Discmans arrived, late-90s millennials still lived on mixtapes that hissed, flipped, and tangled in Walkmans. The last cassette years feel intimate because you made the tape with scissors, labels, and patience.","sensory":"soft tape hiss, clack of Play, warm foam earpads","tag":"Walkman on"},{"name":"Mix CDs / CD binders","category":"media","years":"1997–2001","why":"Before iTunes libraries and Spotify playlists, friendship and crush economics ran on burned or store-bought CDs slid into zippered nylon binders under car seats. Handwritten tracklists, scratched rainbow bottoms, and “track 7 is our song” rituals defined late-90s/early-00s courtship—especially for early millennials who lived the Napster → blank-CD pipeline. The binder was a portable identity dossier you could pass across a lunch table.","sensory":"nylon zipper rasp, jewel-case crack, laser-etched disc iridescence, Sharpie tracklist smell","tag":"with a stack of mix CDs"},{"name":"Disposable cameras","category":"tech","years":"1996–2001","why":"Single-use film cameras were the default capture device for dances, trips, and sleepovers before camera phones—shoot blind, drop the roll at a drugstore, wait days for a surprise stack of 4×6 prints. For Dial-up Dawn millennials, the delay and the flash-pop group shot were the social photo ritual; later Instax/Polaroid revivals echo that chemical surprise. Cardboard crunch and chemical print smell beat any Instagram filter for this cohort.","sensory":"cardboard-plastic crunch, flash pop, chemical print smell, drugstore envelope wait","tag":"with a disposable camera"},{"name":"Translucent iMac / iBook colors","category":"tech","years":"1998–2001","why":"Apple’s Bondi Blue 1998 iMac and fruit-colored follow-ups (and clamshell iBooks) made computers look like candy instead of beige boxes. They are the visual shorthand for “the internet just became a living-room object.”","sensory":"see-through Bondi/blueberry plastic, CRT glass curve, soft startup chime","tag":"with a see-through iMac"},{"name":"Frosted tips (and boy-band hair gel)","category":"fashion accessory","years":"1997–2000","why":"Bleached spikes and chunky peroxide highlights—NSYNC/Backstreet/98 Degrees/Sugar Ray coded—were the default mall-photo masculinity of the late ’90s into Y2K, paired with crunchy hair gel and frosted tips kits sold at every drugstore. Yearbooks from 1998–2000 read like a TRL freeze-frame; the look became a punchline later, which is how you know it was formative.","sensory":"crunchy gel cast, peroxide-bright tips, mall-salon chemical tang","tag":"with frosted tips"},{"name":"Scrunchies","category":"fashion accessory","years":"1995–1999","why":"Fabric hair scrunchies were Dial-up Dawn locker staples—velvet, satin, oversized “cloud” versions—bridging late-90s teen fashion into early-00s mall culture before thin elastics briefly won. Millennial nostalgia revived them hard in the late 2010s, proving the object’s formative stickiness. Sensory memory is the soft fabric bun and the snap of taking one off a backpack strap.","sensory":"soft fabric bun, elastic stretch, backpack-strap snap, velvet/satin sheen","tag":"with a scrunchie"},{"name":"VHS tapes + CRT living-room TV","category":"media","years":"1995–1999","why":"Rewinding Blockbuster rentals on deep-cabinet CRTs was still the default family night before DVD fully won. Tracking lines, tape stickers, and the clunk of a VCR tray are the sensory home of late-90s evenings.","sensory":"warm CRT buzz, tape whir/rewind, plastic clamshell cases","tag":"with a VHS tape to rewind"},{"name":"Furby","category":"toy","years":"1998–1999","why":"Tiger Electronics’ owl-hamster hybrid launched fall 1998 and detonated the holiday toy wars—overnight lines, store stampedes, black-market markups, and ~40M sold in three years. Millennials remember Furbish chatter, no-off-switch lore, and a pet that felt unnervingly alive beside Tamagotchi’s simpler beeps.","sensory":"plush synthetic fur, motorized ear wiggles, Furbish babble + clap responses","tag":"with a Furby"}],"y2k":[{"name":"Razor scooter","category":"toy","years":"2000–2002","why":"The aluminum Razor kick scooter craze (~2000–2002) owned driveways and school sidewalks as the Y2K kid/teen transport meme before Heelys and skateboards reclaimed cool. Folding latch, urethane wheels, and scraped shins define the era’s outdoor physical culture alongside Nokia pockets. Adults banned them from malls almost as reliably as kids raced them downhill.","sensory":"metallic fold-latch click, polyurethane wheel hum, vibrating handlebars","tag":"on a Razor scooter"},{"name":"Game Boy Advance","category":"tech","years":"2001–2004","why":"Launched mid-2001, the wide GBA (then SP with frontlight) carried Pokémon Ruby/Sapphire and a library that defined elementary/middle-school pockets. It bridges chunky 90s handhelds and the coming dual-screen DS era.","sensory":"wide landscape grip, soft face buttons, purple/indigo shell colors","tag":"Game Boy Advance in hand"},{"name":"Original iPod (scroll-wheel era)","category":"music hardware","years":"2001–2004","why":"The white 2001 iPod and its immediate successors made “1,000 songs in your pocket” a status object before earbuds were everywhere. FireWire sync cables and the mechanical click wheel feel like the last analog gesture in digital music.","sensory":"polished white polycarbonate, tactile click wheel, signature white earbuds","tag":"iPod on"},{"name":"Nokia 3310","category":"tech","years":"2000–2003","why":"Released late 2000, Nokia’s 3310 became the everyman candy-bar phone: Snake II, changeable Xpress-on covers, legendary drop survival, and monophonic ringtones that still meme as millennial auditory DNA. It sat between late-90s brick phones and the camera/color-screen wave—formative for teens who got “a phone for emergencies” that still became a social toy. Swap faces and SMS textese culture are as memorable as the hardware toughness myth.","sensory":"rubbery keypad thud, blue-backlit mono LCD, tinny ringtone chirps, clicky cover swaps","tag":"Nokia 3310 in hand"},{"name":"T-Mobile Sidekick (Danger Hiptop)","category":"tech","years":"2002–2006","why":"Danger’s Hiptop shipped nationwide as the T-Mobile Sidekick on Oct 1, 2002—swivel screen, full QWERTY, always-on AIM, email, and a real HTML browser years before the iPhone. Celebrity placement (Jay-Z videos, Paris Hilton/Kim Kardashian purses, athlete editions) made it youth status jewelry; teens bedazzled shells and typed buddy-list life from the mall. It was the fashion smartphone of the MySpace warm-up years, not a corporate BlackBerry clone.","sensory":"swivel-hinge snap, chiclet keyboard clack, bright PDA-like screen","tag":"Sidekick in hand"},{"name":"Bratz dolls","category":"toy","years":"2001–2005","why":"MGA’s Bratz debuted in 2001 with oversized lips, fashion-magazine attitude, and urban outfits that challenged Barbie’s pastel princess default—quickly becoming a playground/status collectible through the mid-2000s. They mark early millennial childhood’s shift toward glossy magazine aspiration and Y2K/McBling fashion literacy (platform shoes, metallic fabrics, clique branding). Media moral panics about “too sexy” only amplified the brand’s cultural footprint.","sensory":"huge glittery eyes, plastic platform shoes, vinyl hair sheen, cardboard fashion packaging","tag":"with Bratz dolls"},{"name":"Heelys","category":"fashion accessory","years":"2000–2005","why":"Launched around 2000, Heelys hid a removable wheel in the heel so kids could walk-then-roll through malls and school halls—millions of pairs sold (company claims ~4.5M by mid-decade) at $60–$100. Schools and malls banned them after hallway collisions, broken arms, and floor wear, which only cemented the mythos. Learning the push-off glide—and hearing “no Heelys”—is pure early-2000s bodily memory.","sensory":"hidden wheel click-in, skating rumble, chunky skate-shoe sole","tag":"on Heelys"},{"name":"Windows XP “Bliss” wallpaper","category":"media","years":"2001–2007","why":"Charles O’Rear’s green Sonoma hill under blue sky shipped as Windows XP’s default “Bliss” wallpaper in 2001 and became one of the most-seen photographs of the decade—homework desktops, AIM windows, and school-lab CRTs all framed by it. It is less a desktop choice than a collective unconscious backdrop for Y2K Horizon millennials, surviving long after Luna chrome UI itself felt dated.","sensory":"saturated green hill, cloud-soft blue sky, CRT/LCD desktop glow","tag":"with Bliss on the screen"},{"name":"Abercrombie & Fitch shopping bags","category":"fashion accessory","years":"2000–2004","why":"Bruce Weber’s shirtless-model bags and Fierce-fogged, nightclub-dark stores turned packaging into a mall status prop—teens carried empty bags and taped the photos to bedroom walls. Under Mike Jeffries the brand sold exclusive “cool kid” belonging as much as polos; carrying A&F paper signaled you had access to that aspirational hierarchy even before you opened the tissue.","sensory":"thick brown paper, loud tissue rustle, Fierce cologne haze","tag":"with an Abercrombie bag"},{"name":"Clear phone cases with stickers","category":"fashion accessory","years":"2000–2005","why":"Hard clear shells over candy-bar and flip phones became collage canvases for holographic stickers, initials, and magazine cutouts. Personalizing a tiny screen device was the craft project before phone wallpapers mattered.","sensory":"hard polycarbonate shell, sticky sticker edges, trapped air bubbles","tag":"with a stickered phone case"},{"name":"DVD keep-cases (tall black Amaray)","category":"media","years":"2001–2006","why":"As DVD overtook VHS in the early 2000s, tall snap-shut Amaray keep-cases became the default rental/retail shell—replacing clunky tape sleeves beside new progressive-scan players. Blockbuster walls and bedroom towers of identical black spines (plus rare colored specialty cases) are early-2000s media furniture before Netflix envelopes and streaming emptied the shelves.","sensory":"brittle plastic snap, booklet paper slide, mirrored disc face","tag":"with a DVD stack"},{"name":"Flip phones (pre-Razr clamshells)","category":"tech","years":"2000–2004","why":"Before the Razr’s fashion peak, everyday Motorola/Nokia/Samsung flips taught the open-to-answer gesture and external caller-ID screens. Closing the phone to hang up still feels more final than tapping a glass slab.","sensory":"hinge snap-shut, external mono screen glow, keypad under thumb","tag":"flip phone in hand"},{"name":"Von Dutch trucker hat","category":"fashion accessory","years":"2002–2004","why":"Mesh-back truckers with the looping Von Dutch logo went from LA custom-car cool to paparazzi uniform after Britney/Justin covers and especially Paris & Nicole on *The Simple Life* (2003 sales ~$33M+). For millennials it is the anti-status status symbol that aged into a punchline almost overnight.","sensory":"foam front + mesh back, plastic snap closure, logo embroidery bump","tag":"in a Von Dutch hat"}],"myspace":[{"name":"Motorola RAZR V3","category":"tech","years":"2004–2007","why":"Motorola’s ultra-thin aluminum RAZR V3 (US late 2004) sold well over 100 million units and was the fashion phone of Profile Peak—mirror finishes, whisper-thin clamshells, and low-battery chirps in every hallway. It defined mid-decade pockets before smartphones made “thin flip phone” obsolete; camera quality was mediocre and that somehow didn’t matter. Closing the RAZR with a wrist flick is still a muscle-memory millennial gesture.","sensory":"cold brushed metal, whisper-thin hinge, insistent low-battery chirp, mirror selfie finish","tag":"Razr in hand"},{"name":"Livestrong yellow bracelet","category":"fashion accessory","years":"2004–2005","why":"Nike’s $1 yellow silicone band for the Lance Armstrong Foundation went viral in summer 2004 and stacked wrists next to every copycat color cause band. It is the object that turned charity into a default accessory.","sensory":"matte yellow silicone stretch, embossed LIVESTRONG type, sweaty wrist seal","tag":"with a Livestrong band"},{"name":"Rubber / silicone awareness bracelets (stack)","category":"fashion accessory","years":"2004–2007","why":"Nike’s yellow Livestrong bands (2004) triggered a mid-decade silicone bracelet explosion—every color a cause, team, or just a look, sold at registers and worn in thick school stacks. Wrists became hardware stores of empathy-as-fashion; the fad’s sincerity and trend-chasing collapsed together, which is exactly why the stacks still read as Profile Peak costume.","sensory":"layered silicone tug, color-coded bands, soft rubber squeak","tag":"with a stack of bracelets"},{"name":"Nintendo DS","category":"tech","years":"2005–2008","why":"The dual-screen, touch-stylus Nintendo DS (NA late 2004/2005) made Nintendogs, Mario Kart DS, Brain Age, and PictoChat lunchtime and car-ride rituals across Profile Peak. Closing the clamshell like a tiny laptop, blowing into the mic for minigames, and trading via local wireless are signature mid-2000s gestures—portable social play just before smartphones ate the same niche. It bridges Game Boy kids into touch-era habits without leaving Nintendo’s hardware lane.","sensory":"dual-screen clamshell click, plastic stylus tap, mic-blow minigames, shoulder-button grip","tag":"DS in hand"},{"name":"iPod nano / shuffle","category":"music hardware","years":"2005–2008","why":"Apple’s Jan 2005 shuffle (under $100, no screen, AutoFill roulette) and Sept 2005 nano (thinner than a #2 pencil, color screen, click wheel) turned iPods from chunky classics into jewelry-scale flash players. Silhouette ads and white earbuds still ruled; clip-on shuffles bouncing on gym shorts and colored nanos in jean pockets are peak mid-decade personal soundtrack hardware before phones ate music.","sensory":"anodized color aluminum, click-wheel whir, white cord tangle","tag":"iPod nano on"},{"name":"Guitar Hero controller","category":"toy","years":"2005–2008","why":"Harmonix/RedOctane’s Guitar Hero hit PS2 in Nov 2005 with a mini Gibson SG–shaped controller—five frets, strum bar, whammy—and became a surprise hit (~$45M in 2005; ~1.5M copies early). Sequels and the billion-dollar franchise turned living rooms into arenas; by 2007–08 GH/Rock Band parties defined mid-decade millennial social gaming before the plastic-instrument bubble burst.","sensory":"rubber fret buttons, strum-bar spring, plastic whammy bar wiggle","tag":"with a Guitar Hero guitar"},{"name":"Wii Remote","category":"tech","years":"2006–2009","why":"Nintendo’s Nov 19, 2006 Wii launched with the motion-sensing Remote; pack-in Wii Sports (outside Japan) made bowling/tennis a living-room sport for non-gamers and helped the console past 100M lifetime units. Dec 2006 CPSC wrist-strap replacements (~2M) after flung remotes smashed TVs entered family lore. Pointing at the sensor bar while relatives argued over bowling is holiday-core hardware memory.","sensory":"white remote rattle, wrist-strap nylon, speaker “ting” of tennis hits","tag":"Wii Remote in hand"},{"name":"Dance Dance Revolution home pad","category":"toy","years":"2001–2006","why":"After arcade cabinets conquered malls, Konami’s soft home mats for PlayStation/PS2/Xbox (~$40 pad + game) pulled DDR into living rooms—U.S. home software passed a million copies by mid-decade. Friends packed foam mats edge-to-edge, Perfect/Great grades scrolling while someone filmed from the couch. Sweaty arrow stomps turned coordination into a basement spectator sport years before Wii Sports owned living-room fitness games.","sensory":"foam-mat thud, arrow panel squeak, booming menu music","tag":"on a DDR pad"},{"name":"BlackBerry (trackball / Pearl–Curve era)","category":"tech","years":"2006–2009","why":"Consumer BlackBerrys (Pearl 2006, Curve 2007) brought addictive physical keyboards and BBM into non-corporate hands right as the iPhone arrived. Thumb-typing on chiclet keys still signals “serious texter” nostalgia.","sensory":"clicky mini keyboard, trackball roll, LED notification blink","tag":"BlackBerry in hand"},{"name":"First-generation iPhone","category":"tech","years":"2007–2008","why":"The June 2007 iPhone replaced keypads with multitouch glass and made “there’s an app for that” inevitable within a few years. Even people who couldn’t afford one remember the store demos and the slide-to-unlock moment.","sensory":"cold glass face, aluminum band, soft unlock chime","tag":"first iPhone in hand"},{"name":"Blockbuster membership cards & late fees","category":"media","years":"2000–2007","why":"Though the chain peaked earlier, mid-2000s Friday-night aisle browsing and dreaded late fees are how millennials remember video stores before Netflix discs and streaming finished them. Blue-yellow branding is pure hangout architecture.","sensory":"plastic membership card, aisle carpet smell, clamshell DVD spines","tag":"with a Blockbuster card"},{"name":"Abercrombie / Hollister moose bags & cologne fog","category":"fashion accessory","years":"2004–2008","why":"Dim, deafening Hollister caves and A&F bags remained mid-decade mall hierarchy even as the brand’s cool cracked. Leaving the store smelling like you fell into a perfume truck is the joke that never dies.","sensory":"dark wood interiors, deafening playlist thump, heavy paper bag handles","tag":"with a Hollister bag"},{"name":"Juicy Couture velour tracksuit","category":"fashion","years":"2003–2008","why":"The cropped terry/velour set with “Juicy” across the seat was McBling’s uniform—airport couture for Paris Hilton years, then mall ubiquity. Sales peaked around 2008 (~$605M, ~100 stores) before recession taste shifted; millennials still clock the J-zipper and rhinestone slogans instantly.","sensory":"soft velour hand-feel, metal J zipper, rhinestone butt lettering glint","tag":"in a Juicy tracksuit"},{"name":"Webkinz plush + adoption code","category":"toy","years":"2005–2009","why":"Ganz launched Webkinz on April 15, 2005: a ~$15 plush whose secret tag code unlocked Webkinz World—decorate rooms, earn KinzCash, play Cash Cow, attend KinzVille Academy. It was the Beanie Babies of the online era for late millennials (and cusp Gen Z siblings), teaching early virtual-economy habits through a physical toy key. Specialty-store shortages and registration spikes made the code feel like treasure; adult nostalgia logins decades later prove how sticky the hybrid object was.","sensory":"soft plush fur, cardboard hang-tag code, bright Flash UI chimes, KinzCash coin pop","tag":"with a Webkinz"}],"tumblr":[{"name":"Silly Bandz","category":"fashion accessory","years":"2008–2010","why":"Buccaneer/Toby Visnick’s shaped silicone bands exploded online in late 2008 and dominated U.S. recess economies ~2009–2010—animal silhouettes stacked as wrist trophies, traded like Pokémon, then banned by schools almost as fast as they arrived. Million-pack weekly sales claims and mall kiosk ubiquity made them the late-millennial fad object bridging toy collecting and fashion accessory. The snap-back sting and rainbow piles are pure Feed Years locker culture.","sensory":"stretched animal silhouette, rainbow silicone stack, snap-back sting, cardboard hang-tag packs","tag":"with Silly Bandz"},{"name":"iPod touch","category":"music hardware","years":"2007–2012","why":"Apple’s Sept 2007 iPod touch was the Wi-Fi multitouch slab for teens who couldn’t get a phone contract—iPod + Safari + YouTube, then App Store games after July 2008. Wi-Fi texting workarounds, Pocket God/Tap Tap Revenge sessions, and white earbuds on school Wi-Fi defined the bridge years before nearly everyone got an actual iPhone.","sensory":"glossy front glass, thin aluminum back, home-button click","tag":"iPod touch in hand"},{"name":"Polaroid / Impossible Project revival film","category":"tech","years":"2010–2014","why":"After Polaroid stopped integral film in 2008, The Impossible Project’s ~2010 relaunch (plus growing Instax) made analog instant cool again for millennials entering adulthood. Waiting for a white square to develop felt newly intentional in a camera-phone world.","sensory":"eject whir, chemical vinegar-sweet smell, developing white frame","tag":"with a Polaroid"},{"name":"Fujifilm Instax Mini cameras","category":"tech","years":"2009–2015","why":"After Polaroid quit integral film in 2008, pastel Instax Minis (widely available by late 2009) became the credit-card instant print millennials actually bought—fashion-blogger/lifestyle marketing pushed ~1M units/year by ~2014, then far beyond. Wallet-sized prints on dorm walls and party strings replaced the old Polaroid shake ritual with a motor spit and soft haze, analog proof in a camera-phone decade.","sensory":"motorized print spit, credit-card photo size, pastel camera shells","tag":"with an Instax"},{"name":"Netflix red envelope","category":"media","years":"2006–2012","why":"Netflix’s DVD-by-mail (1998; iconic red sleeves from 2001) peaked around 2010–11 with roughly 14–20M U.S. subscribers and hundreds of millions of discs/year via USPS—the adult replacement for Blockbuster runs before streaming took over. Queue management, “returned / next disc inbound,” and finding that scarlet mailer in the mailbox is peak late-2000s domestic ritual for millennials living alone or in first apartments.","sensory":"thin red paper sleeve, disc rattle, mailbox cardboard bend","tag":"with a red Netflix envelope"},{"name":"Nintendo DSi / DS Lite","category":"tech","years":"2008–2011","why":"Nintendo’s DS Lite (2006) and camera-toting DSi (2008/09) kept dual-screen handheld culture dominant through the Feed Years—PictoChat carpools, download-play Mario Kart, and DSiWare impulse buys—until the 3DS shifted the form factor. The Lite’s candy colorways (and the DSi’s selfie cameras) are locker-shelf millennial tech as much as “gaming hardware.” Peak overlap with iPhone migration makes this the last mass pre-phone handheld era for many late millennials.","sensory":"slim hinge snap, bright enamel shells, dual-screen stylus scratch, tinny DSi shutter","tag":"DS Lite in hand"},{"name":"Guitar Hero / Rock Band fatigue gear","category":"toy","years":"2008–2010","why":"Controllers piled up through World Tour/Rock Band peaks, then the genre crashed—leaving plastic guitars in closets as fossils. The over-saturation itself is nostalgic: every holiday had another guitar SKU.","sensory":"dusty plastic frets, instrument cable clutter, crowded game-shelf spines","tag":"with a Rock Band drum kit"},{"name":"Early App Store iPhones (3G / 3GS / 4)","category":"tech","years":"2008–2011","why":"iPhone 3G (2008) opened the App Store era; 3GS (2009) and glass-backed iPhone 4 (2010) normalized always-online pockets, Retina screens, and social apps as default adolescence hardware. This is when millennial social life finished migrating from AIM status / MySpace profiles into SMS + apps on one slab—Facebook Messenger, Instagram’s 2010 launch, and location check-ins. Carrier exclusivity drama (AT&T) and the “Antennagate” 4 are part of the folklore.","sensory":"glass sandwich (iPhone 4), Home-button click, vibrate buzz, camera shutter click","tag":"iPhone 4 in hand"},{"name":"BlackBerry Bold / BBM bubble (final peak)","category":"tech","years":"2008–2011","why":"Even as iPhone surged, BlackBerry Bold keyboards and BBM’s blue ticks kept a die-hard campus/professional lane ~2008–2011—typing as status, PIN culture, and read-receipt anxiety before WhatsApp/iMessage normalized it. The tactile keyboard chatter and red LED blink are the last major non-touch millennial phone dialect; Android/iOS erased it fast after the PlayBook/BB10 misfires. For early millennials in white-collar tracks, Bold was “grown-up phone” cosplay.","sensory":"precision keyboard chatter, red LED blink, BBM tone, leatherette back grip","tag":"BBM open"},{"name":"Slap bracelets (playground revival stock)","category":"fashion accessory","years":"2008–2012","why":"Cheap metal-core slap bands returned in toy-aisle waves beside Silly Bandz, teaching a new cohort (and reminding older millennials) of the sharp wrap around the wrist. They sit in this band as a thrifted-90s echo fad, not the original ~1990 boom.","sensory":"sharp metallic slap, glitter vinyl cover, coiled spring tension","tag":"with a slap bracelet"},{"name":"Scrunchies (early revival trickle)","category":"fashion accessory","years":"2011–2014","why":"After a 2000s exile, oversized scrunchies began creeping back onto wrists and Instagram feeds at the turn of the 2010s. For millennials it was less discovery than reclamation of a 90s object they had been taught to mock.","sensory":"velvet pouf return, soft elastic hug, wrist-as-hair-tie habit","tag":"with a scrunchie"},{"name":"Kinect sensor bar","category":"tech","years":"2010–2012","why":"Xbox 360 Kinect (NA Nov 2010) put a black sensor bar on living-room TVs and turned gesture/voice into a party demo—Dance Central, Just Dance crossover energy, and awkward living-room calibration. For late millennials it was the last big console novelty before smartphones ate casual motion play. The glowing green eye and coffee-table stumble zone are Feed Years living-room tech theater.","sensory":"black sensor slab, IR tracking lag, voice “Xbox” prompts","tag":"with a Kinect"},{"name":"Converse Chuck Taylor All Stars","category":"fashion","years":"2008–2012","why":"High-top Chucks were the indie-sleaze / Tumblr-era default under skinny jeans—thrift-adjacent, American Apparel adjacent, and photographable under flash. Millennials wore them as anti-McBling footwear even as the brand stayed mass-market; scuffed white rubber toes mark the look.","sensory":"canvas upper, vulcanized rubber toe cap, flat lace grit","tag":"in Chucks"}],"story":[{"name":"Selfie stick","category":"tech","years":"2014–2016","tag":"selfie stick out","why":"A telescoping pole with a phone clamp turned the front camera into a group shot. Time put it on its best-inventions list in 2014, and museums and stadiums started banning it in 2015.","sensory":"The pole clicks out to full length and the remote button works one time in three."},{"name":"GoPro HERO3 / HERO4","category":"tech","years":"2013–2015","tag":"with a GoPro","why":"The HERO3 (late 2012) and HERO4 (2014) made a matchbox-size camera in a clear waterproof case the default for ski runs, bike rides and dives. The fisheye look spread across YouTube.","sensory":"Strapped to a helmet, filming a fisheye view of your own knees."},{"name":"Fitbit Flex","category":"tech","years":"2013–2016","tag":"Fitbit on","why":"Released in 2013, the Flex was a rubber wristband with a tiny tracker inside. Step counts became something friends compared, and 10,000 a day became a goal people said out loud.","sensory":"Five little dots lighting up when you double-tapped your wrist."},{"name":"iPhone 5c","category":"tech","years":"2013–2015","tag":"iPhone 5c in hand","why":"Apple's 2013 plastic iPhone came in five bright colors with matching rubber cases full of holes. It shipped alongside iOS 7, the update that made the whole phone flat.","sensory":"Glossy plastic in a color you had to commit to for two years."},{"name":"Hoverboard (self-balancing scooter)","category":"toy","years":"2015–2016","tag":"on a hoverboard","why":"Two wheels, no handle, and the top gift of Christmas 2015. Battery fires led to a 2016 US recall of about half a million boards.","sensory":"That first lean forward before it either caught you or didn't."},{"name":"Apple Watch (first model)","category":"tech","years":"2015–2016","tag":"Apple Watch on","why":"The first Apple Watch went on sale in April 2015. Rose gold, a crown you turned like a real watch, and notifications that tapped your wrist.","sensory":"A soft tap on your wrist instead of a buzz in your pocket."},{"name":"Beats headphones","category":"music hardware","years":"2012–2014","tag":"Beats on","why":"Big on-ear headphones with a lowercase b on each side became a status object in school hallways. Apple bought Beats in 2014.","sensory":"The b logo on both ears and bass you could feel in your teeth."},{"name":"Adult coloring books","category":"toy","years":"2015–2016","tag":"with a coloring book","why":"Intricate line drawings sold as a way to switch off. In 2015 coloring books for grown-ups topped bestseller lists and colored-pencil sales jumped.","sensory":"Gel pens, one mandala and an hour without a screen."},{"name":"Pokémon Go on your phone","category":"toy","years":"2016","tag":"Pokémon Go open","why":"Released in July 2016, the phone game sent crowds into parks at night to catch creatures on the map. For a few weeks of that summer it seemed like everyone was playing.","sensory":"Walking into strangers at the park, everyone looking down at the same thing."},{"name":"Amazon Echo","category":"tech","years":"2015–2016","tag":"with an Echo","why":"A black cylinder that listened for its name. It reached US homes in 2015 and made talking to a speaker in the kitchen normal.","sensory":"Saying its name across the kitchen and waiting for the blue ring."},{"name":"PlayStation 4","category":"tech","years":"2013–2016","tag":"with a PS4","why":"Sony's 2013 console had a Share button on the controller, so clips and screenshots went straight online. It outsold its rivals for that whole console generation.","sensory":"The light bar glowing blue on the controller in a dark room."},{"name":"Rainbow Loom bracelets","category":"fashion accessory","years":"2013–2014","tag":"with a Rainbow Loom","why":"A plastic peg board and bags of tiny rubber bands. Kids wove bracelets in class and on the bus until some schools banned them in 2013–14.","sensory":"Tiny rubber bands on every surface of the house for a year."}]};
